// One audit run can log several rotation rows (one per Lokalise project of the product) that share one review sheet: keep one per sheet.
// ingested = 'needs_reason' means the last check found Rejected rows without a reason: re-checked every hour until fixed.
const rows = $input.all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.sheet_id && r.slack_ts && String(r.ingested || '') !== 'yes'; });
const seen = {};
const out = [];
for (const r of rows) {
  if (seen[r.sheet_id]) { continue; }
  seen[r.sheet_id] = true;
  out.push({ json: { row_id: r.id, project_id: r.project_id, project_name: r.project_name, jira_key: r.jira_key, sheet_id: r.sheet_id, slack_ts: String(r.slack_ts), prev: String(r.ingested || '') } });
}
return out;

const REVIEWER = 'U09A8KRRAPM';
const OK = ['white_check_mark', 'heavy_check_mark', 'ballot_box_with_check'];
const pend = $('Pending reviews').all();
const re = $input.all();
for (let i = 0; i < pend.length; i++) {
  const m = (re[i] && re[i].json && re[i].json.message) || {};
  const rs = m.reactions || [];
  const done = rs.some(function (r) { return OK.indexOf(r.name) !== -1 && (r.users || []).indexOf(REVIEWER) !== -1; });
  if (done) { return [{ json: pend[i].json }]; }
}
return [];

const p = $('Pick reviewed sheet').first().json;
// Read every review tab (one per language since 2026-10-07; older sheets have a single 'Findings' tab).
// Since 2026-10-07 the visible tabs have no ID column: rows are matched to _ids by Project | Language | Key | Rule / term | Issue.
// Older sheets that still show an ID column are matched by ID first.
function ck(o) { return ['Project', 'Language', 'Key', 'Rule / term', 'Issue'].map(function (h) { return String(o[h] === undefined || o[h] === null ? '' : o[h]).trim(); }).join('|'); }
const curById = {};
const curByKey = {};
const vr = ($('Read review tabs').first().json.valueRanges) || [];
const rowsCur = [];
for (const r of vr) {
  const vals = r.values || [];
  if (!vals.length) { continue; }
  const head = vals[0].map(function (h) { return String(h); });
  for (let i = 1; i < vals.length; i++) {
    const o = {};
    for (let k = 0; k < head.length; k++) { o[head[k]] = vals[i][k] === undefined ? '' : vals[i][k]; }
    rowsCur.push(o);
    if (o.ID) { curById[String(o.ID)] = o; }
    else if (o.Key || o.Check) { const kk = ck(o); (curByKey[kk] = curByKey[kk] || []).push(o); }
  }
}
if (!vr.length) { throw new Error('Review sheet ' + p.sheet_id + ': no readable tabs - refusing to treat every finding as rejected'); }
function has(col) { return rowsCur.some(function (r) { return Object.prototype.hasOwnProperty.call(r, col); }); }
// Sheet formats, newest first:
//  'Decision' dropdown (2026-10-05): Approved / Rejected; blank = not reviewed (skipped); deleted row = rejected.
//  'Approve? (x)' (2026-10-02): x = approved, unmarked or deleted = rejected.
//  'Reject? (x)' (older): x or deleted = rejected, everything else = approved.
// Sheets with the 'Reason (required if Rejected)' column (2026-10-13): a reason is mandatory for every Rejected row.
// If any is missing, nothing is stored and a reminder is posted; the sheet is re-checked every hour until fixed.
const mode = has('Decision') ? 'decision' : (has('Approve? (x)') ? 'approve' : 'reject');
const strict = has('Reason (required if Rejected)');
const out = [];
const missing = [];
const today = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
for (const it of $('Read original IDs').all()) {
  const o = it.json || {};
  if (!o.ID) { continue; }
  let c = curById[String(o.ID)] || null;
  if (!c) { const l = curByKey[ck(o)]; c = l && l.length ? l.shift() : null; }
  let rejected;
  if (!c) { rejected = true; }
  else if (mode === 'decision') {
    const v = String(c['Decision'] || '').trim().toLowerCase();
    if (v === 'approved') { rejected = false; } else if (v === 'rejected') { rejected = true; } else { continue; }
  }
  else if (mode === 'approve') { rejected = String(c['Approve? (x)'] || '').trim() === ''; }
  else { rejected = String(c['Reject? (x)'] || '').trim() !== ''; }
  const reason = c ? String(c['Reason (required if Rejected)'] || c['Reason (optional)'] || '').trim() : 'row deleted in review';
  if (strict && rejected && c && !reason) { missing.push('• ' + String(o.Language || c.Language || o.ISO || '') + ' — ' + String(o.Key || c.Key || '') + ' (' + String(o['Rule / term'] || c['Rule / term'] || '') + ')'); continue; }
  out.push({ json: { iso: String(o.ISO || ''), project: String(o.Project || (c && c.Project) || p.project_name), decision: rejected ? 'rejected' : 'approved', rule: String(o['Rule / term'] || ''), en: String(o.English || '').slice(0, 400), translation: String(o.Translation || '').slice(0, 400), issue: String(o.Issue || '').slice(0, 300), reason: rejected ? (reason || (mode === 'approve' ? 'not approved in review' : 'rejected in review')) : '', reviewed_at: today } });
}
if (missing.length) { return [{ json: { needs_reason: true, count: missing.length, missing: missing.slice(0, 15), more: Math.max(0, missing.length - 15) } }]; }
return out;

